<?php declare(strict_types=1);namespace App\Interface\Http\Arena;use App\Application\Arena\Service\CloseDuelRoundService;use App\Application\Identity\Service\AuthService;use App\Domain\Arena\Service\DuelScoring;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Arena\ArenaRealtimePublisher;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineArenaPerformanceRecorder;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelRepository;use App\Infrastructure\Persistence\Doctrine\Arena\DoctrineDuelRoundCloser;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Interface\Http\Arena\Controller\ArenaRoundController;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;final class ArenaRoundRouteRegistrar{public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$c=new ArenaRoundController($this->auth,new CloseDuelRoundService(new DoctrineDuelRepository($em),new DoctrineDuelRoundCloser($em,new DuelScoring()),new DoctrineTransactionManager($em),new DoctrineArenaPerformanceRecorder($em)),new ArenaRealtimePublisher($em),$this->responses);$app->post('/v1/arena/duels/{id}/round/close',fn(ServerRequestInterface $r,ResponseInterface $s,array $a):ResponseInterface=>$c->close($r,$s,(string)$a['id']));}}
